  function el(tag, className, text) { const node = document.createElement(tag); if (className) node.className = className; if (text !== undefined) node.textContent = String(text); return node; }
  function add(parent, ...children) { for (const child of children.flat()) if (child != null) parent.append(typeof child === 'string' ? document.createTextNode(child) : child); return parent; }
  function iconNode(name) { return ($(`tools-icon-${name}`) || $('tools-icon-overview')).content.firstElementChild.cloneNode(true); }
  function button(label, fn, kind = 'secondary', symbol) { const node = el('button', `button ${kind}`); node.type = 'button'; add(node, symbol ? iconNode(symbol) : null, label); if (fn) node.addEventListener('click', fn); return node; }
