      study: [t('Group la masomo', 'Study group'), t('Taarifa fupi, ukaribisho na ufutaji wa flood unaotoa nafasi ya mjadala.', 'Concise notices, a welcome and delete-only flood control with room for discussion.')],
      tech: [t('Community ya teknolojia', 'Tech community'), t('Ukaribisho na taarifa fupi. Ulinzi wa command spam unaendelea.', 'A welcome and concise notices. Command spam protection stays in place.')],
