    return ({ 'before:configure': t('Kabla ya kubadili settings', 'Before settings update'), 'before:whitelist_add': t('Kabla ya kuongeza ruhusa ya link', 'Before adding a link allowance'), 'before:whitelist_remove': t('Kabla ya kuondoa ruhusa ya link', 'Before removing a link allowance'), copy_settings: t('Kabla ya kunakili settings', 'Before copying configuration'), restore_settings: t('Kabla ya kurudisha settings', 'Before restoring configuration') })[label] || t('Toleo la mipangilio', 'Configuration snapshot');
